e^{iz₁}/z₁ = e^{ire^{iα}}/(re^{iα}) = e^{ir(cosα + i sinα)}/(re^{iα})
= e^{ir cosα - ir sinα}/(re^{iα})
= (1/r) e^{ir cosα} e^{-i(r sinα + α)}

e^{iz₃}/z₃ = e^{ire^{-iα}}/(re^{-iα}) = e^{ir(cosα - i sinα)}/(re^{-iα})
= e^{ir cosα + ir sinα}/(re^{-iα})
= (1/r) e^{ir cosα} e^{i(r sinα + α)}

z₄ = re^{i(π-α)}

e^{iz₄}/z₄ = e^{-ir cos α} · e^{-ir sin α}/(re^{i(π-α)}) = (1/r) e^{-ir cos α} e^{-i(r sin α + π - α)}
= (1/r) e^{-ir cos α} e^{-i(r sin α - α)} e^{-iπ}
= -(1/r) e^{-ir cos α} e^{-i(r sin α - α)}

z₁ = re^{iα} = r(cos α + i sin α)
iz₁ = ir(cos α + i sin α) = -r sin α + ir cos α
e^{iz₁} = e^{-r sin α} e^{ir cos α}
e^{iz₁}/z₁ = e^{-r sin α} e^{ir cos α}/(re^{iα}) = (e^{-r sin α}/r) e^{i(r cos α - α)}
